SELECT @@session.time_zone AS session_tz, UTC_TIMESTAMP(6) AS now_utc, p.id, p.symbol, p.status, p.realized_pnl, TIMESTAMPADD(MICROSECOND, CAST(ROUND(UNIX_TIMESTAMP(p.closed_at)*1000000) AS SIGNED), '1970-01-01 00:00:00') AS closed_utc, TIMESTAMPADD(HOUR, 3, TIMESTAMPADD(MICROSECOND, CAST(ROUND(UNIX_TIMESTAMP(p.closed_at)*1000000) AS SIGNED), '1970-01-01 00:00:00')) AS closed_ksa FROM paper_position p WHERE p.status = 'CLOSED' AND p.closed_at IS NOT NULL AND p.realized_pnl < 0 ORDER BY p.closed_at DESC LIMIT 6;
SELECT p.status, COUNT(*) AS n, SUM(p.realized_pnl < 0) AS losses, SUM(CASE WHEN p.realized_pnl < 0 THEN p.realized_pnl ELSE 0 END) AS loss_sum, TIMESTAMPADD(MICROSECOND, CAST(ROUND(UNIX_TIMESTAMP(MAX(p.closed_at))*1000000) AS SIGNED), '1970-01-01 00:00:00') AS max_closed_utc, SUM(UNIX_TIMESTAMP(p.closed_at) > UNIX_TIMESTAMP('2026-10-12 07:05:21') ) AS n_after_182_session_tz_note FROM paper_position p GROUP BY p.status;